# FBV — explicit, readable for custom logic
from django.shortcuts import render, redirect, get_object_or_404
from django.contrib.auth.decorators import login_required

@login_required
def article_update(request, pk: int):
    article = get_object_or_404(Article, pk=pk, author=request.user)
    if request.method == 'POST':
        form = ArticleForm(request.POST, instance=article)
        if form.is_valid():
            form.save()
            return redirect('article-detail', pk=pk)
    else:
        form = ArticleForm(instance=article)
    return render(request, 'articles/edit.html', {'form': form})

# CBV — less code for standard CRUD
from django.contrib.auth.mixins import LoginRequiredMixin
from django.views.generic import UpdateView
from django.urls import reverse_lazy

class ArticleUpdateView(LoginRequiredMixin, UpdateView):
    model = Article
    form_class = ArticleForm
    template_name = 'articles/edit.html'

    def get_queryset(self):               # override to scope to current user
        return Article.objects.filter(author=self.request.user)

    def get_success_url(self):
        return reverse_lazy('article-detail', kwargs={'pk': self.object.pk})

# urls.py
from django.urls import path
urlpatterns = [
    path('articles/<int:pk>/edit/', ArticleUpdateView.as_view(), name='article-update'),
]

# DRF APIView — CBV for REST APIs
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status

class ArticleDetail(APIView):
    def get(self, request, pk: int):
        article = get_object_or_404(Article, pk=pk)
        return Response(ArticleSerializer(article).data)

    def put(self, request, pk: int):
        article = get_object_or_404(Article, pk=pk)
        serializer = ArticleSerializer(article, data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)
